/* mulberry32. The whole generator state is one int32 held in S.rng, so a saved
   game resumes the exact same random stream. Math.random is never used. */
function rnd(S) {
  S.rng = (S.rng + 0x6D2B79F5) | 0;
  let t = S.rng;
  t = Math.imul(t ^ (t >>> 15), 1 | t);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const rint = (S, n) => Math.floor(rnd(S) * n);                 // 0..n-1
const rrange = (S, a, b) => a + Math.floor(rnd(S) * (b - a + 1)); // inclusive
