/* Standalone generator used only for map creation, so that terrain depends on
   the seed alone and never on how much randomness gameplay has consumed. */
function makeGen(seed) {
  let s = seed | 0;
  return function () {
    s = (s + 0x6D2B79F5) | 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), 1 | t);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* Deterministic, key-sorted JSON. Used for the state hash so that key insertion
   order can never change a hash. */
function stableStr(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(stableStr).join(',') + ']';
  const keys = Object.keys(v).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + stableStr(v[k])).join(',') + '}';
}
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}
/* Hash of everything that matters mechanically. Numbers are rounded to 3dp so
   that float noise below gameplay resolution cannot flip a hash. */
function stateHash(S) {
  const norm = x => {
    if (typeof x === 'number') return Math.round(x * 1000) / 1000;
    if (Array.isArray(x)) return x.map(norm);
    if (x && typeof x === 'object') {
      const o = {};
      for (const k of Object.keys(x)) o[k] = norm(x[k]);
      return o;
    }
    return x;
  };
  return fnv1a(stableStr(norm(S)));
}

