// Temporary verification harness (lives in /tmp, not in the deliverable dir).
const fs = require('fs');
const path = '/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t13/game.html';
const src = fs.readFileSync(path, 'utf8');
const js = src.match(/<script>([\s\S]*)<\/script>/)[1];

// --- minimal DOM stub -------------------------------------------------------
function makeEl(id) {
  const el = {
    id: id, value: '', textContent: '', innerHTML: '', style: {}, offsetWidth: 10, offsetHeight: 10,
    classList: { add(){}, remove(){}, toggle(){} },
    getBoundingClientRect(){ return {left:0,top:0,right:0,bottom:0}; },
    getAttribute(){ return null; }, setAttribute(){}, hasAttribute(){ return false; },
    select(){}, querySelectorAll(){ return []; }, querySelector(){ return null; },
    closest(){ return null; }, scrollTop: 0
  };
  return el;
}
const els = {};
global.document = {
  getElementById(id){ if(!els[id]) els[id]=makeEl(id); return els[id]; },
  querySelectorAll(){ return []; },
  querySelector(){ return null; },
  addEventListener(){}
};
global.window = { innerWidth: 1000, innerHeight: 800, addEventListener(){}, performance: { now: () => 0 } };
global.performance = { now: () => 0 };

// --- run the game script ----------------------------------------------------
const ctx = {};
const wrapped = js + '\n;module.exports={runTests,runBenchmark,newGame,greedyTurn,stateHash,serialize,deserialize,scoreOf,caps,RES,TECH_IDS,S:()=>S,avgMorale,countBld,housing,endTurn,resolveChoice,actResearch,techState};';
const mod = { exports: {} };
new Function('module', 'require', 'global', wrapped)(mod, require, global);
const G = mod.exports;

console.log('=== LOAD OK ===');

// 1. tests
const t = G.runTests();
let pass = 0;
t.forEach(x => { if (x.pass) pass++; console.log((x.pass ? 'PASS  ' : 'FAIL  ') + x.name + (x.note ? '\n        -> ' + x.note : '')); });
console.log(`--- ${pass}/${t.length} assertions passed ---`);

// 2. benchmark determinism + balance probe
const t0 = Date.now();
const b1 = G.runBenchmark(1337, 200);
const b2 = G.runBenchmark(1337, 200);
console.log('\n=== BENCHMARK seed 1337 x200 turns ===');
console.log(JSON.stringify(b1, null, 1));
console.log('repeat hash match:', b1.hash === b2.hash);
console.log('elapsed ms:', Date.now() - t0);

// 3. Winnability probe: greedy policy over a real 60-turn game (end conditions ON)
console.log('\n=== WINNABILITY PROBE (greedy policy, end conditions active) ===');
for (const seed of [1337, 42, 7, 999, 2024, 31337]) {
  const S = G.newGame(seed);
  let guard = 0;
  while (!S.over && guard++ < 200) G.greedyTurn(S);
  console.log(`seed ${String(seed).padStart(6)}  turn ${String(S.turn).padStart(3)}  pop ${String(S.pop.length).padStart(2)}  ` +
    `morale ${String(Math.round(G.avgMorale(S))).padStart(3)}  tech ${G.scoreOf(S).techDone}  ` +
    `win ${S.over ? S.over.win : '?'}  score ${S.over ? S.over.score : '-'}`);
}

// 4. Losability probe: do-nothing player
console.log('\n=== DO-NOTHING PROBE (no builds, no assignments) ===');
for (const seed of [1337, 42]) {
  const S = G.newGame(seed);
  let guard = 0;
  while (!S.over && guard++ < 200) { if (S.pending) G.resolveChoice(S, 0); G.endTurn(S); }
  console.log(`seed ${seed}: ended turn ${S.turn}, pop ${S.pop.length}, win ${S.over.win}, score ${S.over.score}`);
}
